CREATE TABLE IF NOT EXISTS "default"."otel_traces_trace_id_ts"  (
    TraceId String CODEC(ZSTD({p1:Int64})),
    Start DateTime CODEC(Delta, ZSTD({p2:Int64})),
    End DateTime CODEC(Delta, ZSTD({p3:Int64})),
    INDEX idx_trace_id TraceId TYPE bloom_filter({p4:Float64}) GRANULARITY {p5:Int64}
) ENGINE = MergeTree()
    PARTITION BY toDate(Start)
    ORDER BY (TraceId, Start)
    TTL toDateTime(Start) + toIntervalDay({p6:Int64})
    SETTINGS index_granularity={p7:Int64}, ttl_only_drop_parts = {p8:Int64}
